exercises.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  04 · split the bill                                         ★★★ stretch
//  concepts: even allocation · remainder distribution
// ─────────────────────────────────────────────────────────────────────────
//
//  $1.00 split three ways is not 33.33 × 3. The parts must SUM to the
//  total exactly — the leftover cents go to the first parts.

using static Bootcamp.Check;

List<long> Allocate(long totalCents, int ways)
{
    long share = totalCents / ways;
    long extra = totalCents % ways;
    var parts = new List<long>();
    for (int i = 0; i < ways; i++)
        parts.Add(share + (i < extra ? 1 : 0));
    return parts;
}

